import{c as a,Q as n,j as r,m as t}from"./chunks/framework.BXc4yaFE.js";const d=JSON.parse('{"title":"PhoneHarness: Harnessing Phone-Use Agents through Mixed GUI, CLI, and Tool Actions","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.14832","title":"PhoneHarness: Harnessing Phone-Use Agents through Mixed GUI, CLI, and Tool Actions","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2606.14832,"authors":["Chenxin Li","Zhengyao Fang","Zhengyang Tang","Pengyuan Lyu","Xingran Zhou","Xin Lai","Fei Tang","Liang Wu","Yiduo Guo","Weinong Wang","Junyi Li","Yi Zhang","Yang Ding","Huawen Shen","Sunqi Fan","Shangpin Peng","Zheng Ruan","Anran Zhang","Benyou Wang","Chengquan Zhang","Han Hu"],"domains":["cs.CL"],"html":"https://arxiv.org/html/2606.14832v1","pdf_path":"pdfs/2606.14832.pdf","published_date":"2026-06-12T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-12-phoneharness-mixed-gui-cli-tool-actions-2606-14832.md","filePath":"research/papers/2026-06-12-phoneharness-mixed-gui-cli-tool-actions-2606-14832.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-06-12-phoneharness-mixed-gui-cli-tool-actions-2606-14832.md"};function s(i,e,h,l,g,c){return n(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="phoneharness-harnessing-phone-use-agents-through-mixed-gui-cli-and-tool-actions" tabindex="-1">PhoneHarness: Harnessing Phone-Use Agents through Mixed GUI, CLI, and Tool Actions <a class="header-anchor" href="#phoneharness-harnessing-phone-use-agents-through-mixed-gui-cli-and-tool-actions" aria-label="Permalink to &quot;PhoneHarness: Harnessing Phone-Use Agents through Mixed GUI, CLI, and Tool Actions&quot;">​</a></h1><p><strong>Authors</strong>: Chenxin Li, Zhengyao Fang, Zhengyang Tang, Pengyuan Lyu, Xingran Zhou, Xin Lai, Fei Tang, Liang Wu, Yiduo Guo, Weinong Wang, Junyi Li, Yi Zhang, Yang Ding, Huawen Shen, Sunqi Fan, Shangpin Peng, Zheng Ruan, Anran Zhang, Benyou Wang, Chengquan Zhang, Han Hu <strong>Published</strong>: June 12, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.14832" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.14832</a> · <a href="https://arxiv.org/html/2606.14832v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.14832 <strong>Categories</strong>: cs.CL <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.14832" target="_blank" rel="noreferrer">research/papers/pdfs/2606.14832.pdf</a> (16 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Phone agents are increasingly expected to complete real mobile workflows rather than merely predict the next screen action. However, much of the current mobile-agent literature still evaluates agents primarily as GUI controllers that observe a screen, emit taps and swipes, and are scored by target app state. Real phone-use tasks are broader: they require deciding when to use app GUIs, device-side commands, or structured tools, while leaving evidence that the intended side effect actually occurred. We introduce PhoneHarness, a mixed-action benchmark and execution harness for studying phone-use agents on verifiable mobile workflows [...].</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><p><strong>PhoneHarness</strong> = 同時為 <strong>mixed-action benchmark + execution harness</strong>，研究 phone-use agent 在「可驗證 mobile workflow」上的表現。核心觀點：真實 phone 任務不只是 GUI 控制，而需在 <strong>GUI / device-side CLI / structured tool</strong> 間決策，並留下「side effect 確實發生」的證據。</p><ol><li><strong>Mixed-action 空間</strong> — 跨 GUI、CLI、host-side tool 的動作面。</li><li><strong>Deterministic routing</strong> — 確定性路由決定動作面。</li><li><strong>Auditable execution traces / verifiable side effect</strong> — 以可稽核 trace 驗證任務真有發生（非僅看 app 終態）。</li></ol><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>標註評估 split 上 <strong>75.0% pass rate</strong>，超可比系統 <strong>+12.9 個百分點</strong>。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>未列明確 limitation 章節；隱含主張「可靠 phone 自動化取決於 action-surface routing + 可驗證執行，而非純視覺 GUI 控制」。</li></ul><h3 id="命名注意" tabindex="-1">命名注意 <a class="header-anchor" href="#命名注意" aria-label="Permalink to &quot;命名注意&quot;">​</a></h3><ul><li>與既有 HarnessX（2606.14249）非同源；此為 phone-use agent 專用 harness/benchmark。</li></ul><h3 id="收錄注意" tabindex="-1">收錄注意 <a class="header-anchor" href="#收錄注意" aria-label="Permalink to &quot;收錄注意&quot;">​</a></h3><ul><li>與 HarnessX 同日（2026-06-12）發布；屬上批 06-12 cutoff 邊界，本輪一併補收。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li><strong>「action-surface routing 為確定性決定」呼應跨切紀律</strong>：deterministic routing + verifiable side effect = 「路由交確定性代碼、驗證不可省」的 mobile 場景實例。</li><li><strong>verifiable side effect = <code>unverified_success</code> 閘門</strong>：不看終態看「真有發生」的稽核 trace，正是 core.md「靜態檢查 ≠ 端到端執行」的具體化。</li><li>⚠️ 域為 mobile/phone-use，與本 workspace 場景錯位；價值在 harness 設計理念（mixed-action + verifiable trace），非 benchmark 直接套用（P2 域外參考）。</li></ul>',21)])])}const p=a(o,[["render",s]]);export{d as __pageData,p as default};
